fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);

    // Helper function to broadcast a single-length array to length max_len
    fn broadcast(arr: &Vec<i8>, len: usize) -> Vec<i8> {
        if arr.len() == 1 {
            vec![arr[0]; len]
        } else {
            arr.clone()
        }
    }

    let a_broadcasted = if m == 1 && max_len > 1 {
        broadcast(&a, max_len)
    } else if m == max_len {
        a.clone()
    } else {
        // This branch theoretically shouldn't happen if inputs are compatible,
        // but we fallback to broadcasting just in case
        broadcast(&a, max_len)
    };

    let b_broadcasted = if n == 1 && max_len > 1 {
        broadcast(&b, max_len)
    } else if n == max_len {
        b.clone()
    } else {
        // Fallback for completeness (should not occur if inputs compatible)
        broadcast(&b, max_len)
    };

    (a_broadcasted, b_broadcasted)
}